; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti89 (TI-89 / 92+ / V200 (68000, AMS)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_ti89_boot
; (the 68k backend requires this section be named ntc_md_vectors - the generic
;  "68k start" slot. On AMS there is no program-owned vector table; this is just
;  the entry. ;!!TI89? the real AMS nostub header/reloc goes here - stubbed.)
			bra ntc_ti89_boot

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dc.l kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 21: Cls
			dc.l kw_cls

			; 22: Print "VB self test 6"
			dc.l kw_printstrvar, str0
			dc.l kw_printnl

			; 25: For i = 0 To 9
			dc.l kw_ztov, var_i
for1_t:

			; 26: buf(i) = i * 30
			dc.l kw_mulvl, var_i, 30, tmp1
			dc.l kw_aset8, arr_buf, var_i, tmp1

			; 27: Next
			dc.l kw_next1l, var_i, 9, for1_t
for1_e:

			; 28: Chk buf(9), 14          ' 270 And 255
			dc.l kw_lptrtov8, arr_buf+9, tmp0
			dc.l p_chk_c, tmp0, lit_14

			; 29: Chk buf(2), 60
			dc.l kw_lptrtov8, arr_buf+2, tmp0
			dc.l p_chk_c, tmp0, lit_60

			; 30: i = 3
			dc.l kw_ltov, 3, var_i

			; 31: Chk buf(i), 90
			dc.l kw_aget8, arr_buf, var_i, tmp0
			dc.l p_chk_c, tmp0, lit_90

			; 32: buf(0) = 255
			dc.l kw_ltolptr8, 255, arr_buf

			; 33: Chk buf(0), 255
			dc.l kw_lptrtov8, arr_buf, tmp0
			dc.l p_chk_c, tmp0, lit_255

			; 34: Chk ByteSum(buf), 255 + 30 + 60 + 90 + 120 + 150 + 180 + 210 + 240 + 14
			dc.l p_bytesum_c, ad_arr_buf
			dc.l kw_vtov, var_bytesum_bytesum, tmp0
			dc.l p_chk_c, tmp0, lit_1349

			; 37: ReDim dyn(5)
			dc.l kw_redim, pa_dyn, pa_dyn_data, 0, 2, 6, 1

			; 38: Chk UBound(dyn), 5
			dc.l kw_ubound, pa_dyn, tmp0
			dc.l p_chk_c, tmp0, lit_5

			; 39: Chk LBound(dyn), 0
			dc.l kw_lbound, pa_dyn, tmp0
			dc.l p_chk_c, tmp0, lit_0

			; 40: For i = 0 To 5
			dc.l kw_ztov, var_i
for2_t:

			; 41: dyn(i) = i * i
			dc.l kw_mulvv, var_i, var_i, tmp2
			dc.l kw_pset, pa_dyn, var_i, tmp2

			; 42: Next
			dc.l kw_next1l, var_i, 5, for2_t
for2_e:

			; 43: Chk dyn(5), 25
			dc.l kw_pget, pa_dyn, lit_5, tmp0
			dc.l p_chk_c, tmp0, lit_25

			; 44: ReDim Preserve dyn(BIGN)
			dc.l kw_redim, pa_dyn, pa_dyn_data, 0, 2, 21, 0

			; 45: Chk UBound(dyn), 20
			dc.l kw_ubound, pa_dyn, tmp0
			dc.l p_chk_c, tmp0, lit_20

			; 46: Chk dyn(4), 16
			dc.l kw_pget, pa_dyn, lit_4, tmp0
			dc.l p_chk_c, tmp0, lit_16

			; 47: dyn(20) = 7
			dc.l kw_pset, pa_dyn, lit_20, lit_7

			; 48: Chk dyn(20), 7
			dc.l kw_pget, pa_dyn, lit_20, tmp0
			dc.l p_chk_c, tmp0, lit_7

			; 49: ReDim dyn(1 To 3)
			dc.l kw_redim, pa_dyn, pa_dyn_data, 1, 2, 3, 1

			; 50: Chk LBound(dyn), 1
			dc.l kw_lbound, pa_dyn, tmp0
			dc.l p_chk_c, tmp0, lit_1

			; 51: Chk dyn(1), 0           ' cleared without Preserve
			dc.l kw_pget, pa_dyn, lit_1, tmp0
			dc.l p_chk_c, tmp0, lit_0

			; 52: dyn(3) = 9
			dc.l kw_pset, pa_dyn, lit_3, lit_9

			; 53: Chk Total(dyn), 9
			dc.l p_total_c, pa_dyn
			dc.l kw_vtov, var_total_total, tmp0
			dc.l p_chk_c, tmp0, lit_9

			; 54: Erase dyn
			dc.l kw_redim, pa_dyn, pa_dyn_data, 0, 2, 0, 0

			; 55: Chk UBound(dyn), -1
			dc.l kw_ubound, pa_dyn, tmp0
			dc.l p_chk_c, tmp0, lit_m1

			; 57: ReDim names(2)
			dc.l kw_redim, pa_names, pa_names_data, 0, 41, 3, 1

			; 58: names(1) = "dyn"
			dc.l kw_psets, pa_names, lit_1, str1

			; 59: Chk Len(names(1)), 3
			dc.l kw_pget, pa_names, lit_1, stmp0
			dc.l kw_strlen, stmp0, tmp0
			dc.l p_chk_c, tmp0, lit_3

			; 60: ReDim big(1)
			dc.l kw_redim, pa_big, pa_big_data, 0, 4, 2, 1

			; 61: big(1) = 100000
			dc.l kw_pset, pa_big, lit_1, llit_100000

			; 62: Chk big(1) \ 1000, 100
			dc.l kw_pget, pa_big, lit_1, ltmp0
			dc.l kw_l_div, ltmp0, llit_1000, ltmp0
			dc.l kw_l_ltoi, ltmp0, tmp0
			dc.l p_chk_c, tmp0, lit_100

			; 65: fixed(2) = 5
			dc.l kw_ltov, 5, arr_fixed+4

			; 66: Erase fixed
			dc.l kw_erase, arr_fixed, 10

			; 67: Chk fixed(2), 0
			dc.l p_chk_c, arr_fixed+4, lit_0

			; 70: ReDim recs(2)
			dc.l kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 3, 1
			dc.l kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 3, 1

			; 71: For i = 0 To 2
			dc.l kw_ztov, var_i
for3_t:

			; 72: recs(i).n = i * 5
			dc.l kw_mulvl, var_i, 5, tmp2
			dc.l kw_pset, pa_recs_n, var_i, tmp2

			; 73: recs(i).nm = "r" & i
			dc.l kw_strcstr, stmp3, var_i
			dc.l kw_strcpy, stmp2, str2
			dc.l kw_strcat, stmp2, stmp3
			dc.l kw_psets, pa_recs_nm, var_i, stmp2

			; 74: Next
			dc.l kw_next1l, var_i, 2, for3_t
for3_e:

			; 75: Chk UBound(recs), 2
			dc.l kw_ubound, pa_recs_n, tmp0
			dc.l p_chk_c, tmp0, lit_2

			; 76: Chk Len(recs(1).nm) + recs(2).n, 12
			dc.l kw_pget, pa_recs_nm, lit_1, stmp0
			dc.l kw_strlen, stmp0, tmp0
			dc.l kw_pget, pa_recs_n, lit_2, tmp1
			dc.l kw_add, tmp0, tmp1, tmp0
			dc.l p_chk_c, tmp0, lit_12

			; 77: ReDim Preserve recs(4)
			dc.l kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 5, 0
			dc.l kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 5, 0

			; 78: Chk recs(2).n, 10
			dc.l kw_pget, pa_recs_n, lit_2, tmp0
			dc.l p_chk_c, tmp0, lit_10

			; 79: Erase recs
			dc.l kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 0, 0
			dc.l kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 0, 0

			; 80: Chk UBound(recs), -1
			dc.l kw_ubound, pa_recs_n, tmp0
			dc.l p_chk_c, tmp0, lit_m1

			; 82: Print
			dc.l kw_printnl

			; 83: Print t; " tests, "; bad; " failed"
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str3
			dc.l kw_printint, var_bad
			dc.l kw_printstrvar, str4
			dc.l kw_printnl

			; 84: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str5
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; sub chk (turbo mode)
; ============================================================

p_chk:

			; 87: t = t + 1
			dc.l kw_inc, var_t

			; 88: Print t; ":";
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str6

			; 89: If got = want Then
			dc.l kw_cpeqvv, var_chk_got, var_chk_want
			dc.l kw_goto_iffalse, if4_1

			; 90: Print "ok ";
			dc.l kw_printstrvar, str7

			; 91: Else
			dc.l if4_e_go
if4_1:

			; 92: Print "FAIL("; got; ") ";
			dc.l kw_printstrvar, str8
			dc.l kw_printint, var_chk_got
			dc.l kw_printstrvar, str9

			; 93: bad = bad + 1
			dc.l kw_inc, var_bad

			; 94: End If
if4_e:
			dc.l p_chk_r

; ============================================================
; function bytesum (turbo mode)
; ============================================================

p_bytesum:

			; 98: Dim k As Integer

			; 99: ByteSum = 0
			dc.l kw_ztov, var_bytesum_bytesum

			; 100: For k = LBound(b) To UBound(b)
			dc.l kw_lbound, pa_bytesum_b, var_bytesum_k
			dc.l kw_ubound, pa_bytesum_b, for5_l
			dc.l kw_forupv, var_bytesum_k, for5_l, for5_e
for5_t:

			; 101: ByteSum = ByteSum + b(k)
			dc.l kw_ztov, tmp1
			dc.l kw_pget, pa_bytesum_b, var_bytesum_k, tmp1
			dc.l kw_add, var_bytesum_bytesum, tmp1, var_bytesum_bytesum

			; 102: Next
			dc.l kw_next1v, var_bytesum_k, for5_l, for5_t
for5_e:
			dc.l p_bytesum_r

; ============================================================
; function total (turbo mode)
; ============================================================

p_total:

			; 106: Dim k As Integer

			; 107: Total = 0
			dc.l kw_ztov, var_total_total

			; 108: For k = LBound(a) To UBound(a)
			dc.l kw_lbound, pa_total_a, var_total_k
			dc.l kw_ubound, pa_total_a, for6_l
			dc.l kw_forupv, var_total_k, for6_l, for6_e
for6_t:

			; 109: Total = Total + a(k)
			dc.l kw_pget, pa_total_a, var_total_k, tmp1
			dc.l kw_add, var_total_total, tmp1, var_total_total

			; 110: Next
			dc.l kw_next1v, var_total_k, for6_l, for6_t
for6_e:
			dc.l p_total_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if4_e_go:			lea if4_e, sp
			rts

p_chk_c:		; call chk
			movea.l (sp)+, a0		; got
			move.w (a0), var_chk_got
			movea.l (sp)+, a0		; want
			move.w (a0), var_chk_want
			move.l sp, p_chk_rs
			lea p_chk, sp
			rts
p_chk_r:		; end of chk
			movea.l p_chk_rs, sp
			rts
p_bytesum_c:		; call bytesum
			movea.l (sp)+, a0		; b() descriptor
			lea pa_bytesum_b, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_bytesum_bytesum
			clr.w var_bytesum_k
			move.l sp, p_bytesum_rs
			lea p_bytesum, sp
			rts
p_bytesum_r:		; end of bytesum
			movea.l p_bytesum_rs, sp
			rts
p_total_c:		; call total
			movea.l (sp)+, a0		; a() descriptor
			lea pa_total_a, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_total_total
			clr.w var_total_k
			move.l sp, p_total_rs
			lea p_total, sp
			rts
p_total_r:		; end of total
			movea.l p_total_rs, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; numbers passed by address (read only)
			even
ntc_aptab:		dc.l 0		; AddressOf: the procedures CallAddr runs, by number
lit_14:			dc.w 14
lit_60:			dc.w 60
lit_90:			dc.w 90
lit_255:			dc.w 255
lit_1349:			dc.w 1349
lit_5:			dc.w 5
lit_0:			dc.w 0
lit_25:			dc.w 25
lit_20:			dc.w 20
lit_4:			dc.w 4
lit_16:			dc.w 16
lit_7:			dc.w 7
lit_1:			dc.w 1
lit_9:			dc.w 9
lit_3:			dc.w 3
lit_m1:			dc.w -1
llit_100000:			dc.l 100000
llit_1000:			dc.l 1000
lit_100:			dc.w 100
lit_2:			dc.w 2
lit_12:			dc.w 12
lit_10:			dc.w 10

; ============================================================
; Strings
; ============================================================

str0:			dc.b "VB self test 6", 0
str1:			dc.b "dyn", 0
str2:			dc.b "r", 0
str3:			dc.b " tests, ", 0
str4:			dc.b " failed", 0
str5:			dc.b "Press a key", 0
str6:			dc.b ":", 0
str7:			dc.b "ok ", 0
str8:			dc.b "FAIL(", 0
str9:			dc.b ") ", 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_forupv ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d1
			cmp.w (a0), d1
			blt ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_next1v ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			addq.w #1, (a0)
			bvs ntc_for_skip
			move.w (a1), d1
			cmp.w (a0), d1
			bge ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_inc
kw_inc:
			movea.l (sp)+, a0
			addq.w #1, (a0)
			rts

			even
;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			add.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvv
;kw_mulvv, <var1>, <var2>, <destvar>  - low 16 bits
kw_mulvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			muls.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvl
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			muls.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_cpeqvv
kw_cpeqvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			cmp.w (a1), d0
			rts

			even
;## kw_lptrtov8
;kw_lptrtov8, <literaladdr>, <destvar>  - PEEK(literal)
kw_lptrtov8:
			move.l (sp)+, d0
			movea.w d0, a0
			moveq #0, d0
			move.b (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_ltolptr8
;kw_ltolptr8, <literal>, <literaladdr>  - POKE literal, literal
kw_ltolptr8:
			move.l (sp)+, d0
			move.l (sp)+, d1
			movea.w d1, a0
			move.b d0, (a0)
			rts

			even
;## kw_aget8
;kw_aget8, <arraybase>, <indexvar>, <destvar>  - Byte array element (0 .. 255)
kw_aget8:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			moveq #0, d1
			move.b 0(a0, d0.l), d1
			movea.l (sp)+, a1
			move.w d1, (a1)
			rts

			even
;## kw_aset8
;kw_aset8, <arraybase>, <indexvar>, <sourcevar>  - set a Byte array element (low byte)
kw_aset8:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			movea.l (sp)+, a1
			move.b 1(a1), 0(a0, d0.l)
			rts

			even
;## kw_erase
;kw_erase, <base>, <bytes>  - Erase of a fixed size array: zero it
kw_erase:
			movea.l (sp)+, a0
			move.l (sp)+, d0
ntc_zerofill:					; a0 = start, d0.w = bytes (unsigned)
			andi.l #$FFFF, d0
			beq ntc_zf_end
			subq.l #1, d0
ntc_zf_lp:
			clr.b (a0)+
			dbra d0, ntc_zf_lp
ntc_zf_end:
			rts

			even
;## kw_redim kw_erase
;kw_redim, <descriptor>, <base>, <lower>, <size>, <count>, <clear>  - ReDim: fill the
;  descriptor (1 dimension); clear <> 0: zero the elements. Descriptor (12 bytes):
;  base (16 bits: RAM), lower 1, lower 2, count 1, count 2, element size
kw_redim:
			movea.l (sp)+, a1
			move.l (sp)+, d3			; base
			move.l (sp)+, d4			; lower
			move.l (sp)+, d5			; size
			move.l (sp)+, d6			; count
			move.l (sp)+, d7			; clear
			move.w d3, (a1)
			move.w d4, 2(a1)
			clr.w 4(a1)
			move.w d6, 6(a1)
			move.w #1, 8(a1)
			move.w d5, 10(a1)
			tst.w d7
			beq kw_rd_end
			movea.l d3, a0
			mulu.w d5, d6
			move.l d6, d0
kw_rd_lp:
			clr.b (a0)+
			subq.l #1, d0
			bhi kw_rd_lp
kw_rd_end:
			rts

; ============================================================
; Random (16 bit xorshift 7,9,8 - the Z80 library's sequence)
; ============================================================

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
kw_sc_end:
			tst.b (a1)
			beq kw_sc_copy
			addq.l #1, a1
			subq.w #1, d1
			bgt kw_sc_end
			rts
kw_sc_copy:
			tst.w d1
			beq kw_sc_none
			subq.w #1, d1
kw_sc_lp:
			move.b (a0)+, (a1)+
			dbeq d1, kw_sc_lp
			beq kw_sc_none
			clr.b (a1)
kw_sc_none:
			rts

			even
;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			movea.l (sp)+, a0
			moveq #-1, d0
kw_sl_lp:
			addq.w #1, d0
			tst.b (a0)+
			bne kw_sl_lp
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_cls ntc_data ntc_plat_screen
kw_cls:
			NTC_RS
			jsr ntc_plat_cls
			NTC_TS
			rts

			even
;## kw_strcstr ntc_itoa
;kw_strcstr, <dest>, <nvar>  - number to text (CStr, "x" & n)
kw_strcstr:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_next, a6
			bra ntc_itoa

			even
;## ntc_paddr
; a0 = descriptor, a1 = index var: a0 = element address, d1 = element size. jmp (a6)
ntc_paddr:
			move.w (a1), d0
			sub.w 2(a0), d0				; element number
ntc_pa_tail:					; d0.w = element number, a0 = descriptor
			move.w 10(a0), d1
			movea.w (a0), a0
			muls.w d1, d0
			adda.l d0, a0
			jmp (a6)

			even
;## kw_pget ntc_paddr
;kw_pget, <descriptor>, <indexvar>, <dest>  - dest = parameter array(index)
kw_pget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pg_a, a6
			bra ntc_paddr
kw_pg_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: into the Integer's low byte
			bne kw_pg_n1
			clr.b (a1)+
kw_pg_n1:
			subq.w #1, d1
kw_pg_lp:
			move.b (a0)+, (a1)+
			dbra d1, kw_pg_lp
			rts

			even
;## kw_pset ntc_paddr
;kw_pset, <descriptor>, <indexvar>, <src>  - parameter array(index) = src
kw_pset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_ps_a, a6
			bra ntc_paddr
kw_ps_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: from the Integer's low byte
			bne kw_ps_n1
			addq.l #1, a1
kw_ps_n1:
			subq.w #1, d1
kw_ps_lp:
			move.b (a1)+, (a0)+
			dbra d1, kw_ps_lp
			rts

			even
;## kw_psets ntc_paddr kw_strcpy
;kw_psets, <descriptor>, <indexvar>, <src>  - String parameter array(index) = src
kw_psets:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pss_a, a6
			bra ntc_paddr
kw_pss_a:
			movea.l a0, a1
			movea.l (sp)+, a0
			subq.w #1, d1
			bra ntc_strcpy_lp

			even
;## kw_lbound
;kw_lbound, <descriptor + 2 * (dimension - 1)>, <dest>  - LBound
kw_lbound:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w 2(a0), (a1)
			rts

			even
;## kw_ubound
;kw_ubound, <descriptor + 2 * (dimension - 1)>, <dest>  - UBound = lower bound + count - 1
kw_ubound:
			movea.l (sp)+, a0
			move.w 2(a0), d0
			add.w 6(a0), d0
			subq.w #1, d0
			movea.l (sp)+, a1
			move.w d0, (a1)
			rts

; ============================================================
; Long (32 bit signed): a 68000 long. Every argument is an address
; (a literal is a dc.l in the ROM).
; ============================================================

			even
;## kw_l_ltoi
;kw_l_ltoi, <long>, <intdest>  - Long to Integer (low 16 bits)
kw_l_ltoi:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w 2(a0), (a1)
			rts

			even
;## ntc_lmul
; d0.l * d1.l -> d0.l (low 32 bits). jmp (a6). Uses d2, d3
ntc_lmul:
			move.l d0, d2
			move.l d1, d3
			swap d2
			swap d3
			mulu.w d1, d2				; a_hi * b_lo
			mulu.w d0, d3				; a_lo * b_hi
			add.w d3, d2
			swap d2
			clr.w d2
			mulu.w d1, d0				; a_lo * b_lo
			add.l d2, d0
			jmp (a6)

			even
;## ntc_ldiv
; d0.l / d1.l signed, truncating: d0 = quotient, d1 = remainder (the dividend's
; sign). Divide by 0: quotient 0, remainder = dividend. jmp (a6). Uses d2-d5
ntc_ldiv:
			tst.l d1
			bne ntc_ld_nz
			move.l d0, d1
			moveq #0, d0
			jmp (a6)
ntc_ld_nz:
			move.l d0, d4				; the dividend's sign
			move.l d0, d5
			eor.l d1, d5				; the quotient's sign
			tst.l d0
			bpl ntc_ld_ap
			neg.l d0
ntc_ld_ap:
			tst.l d1
			bpl ntc_ld_bp
			neg.l d1
ntc_ld_bp:
			moveq #0, d2				; remainder
			moveq #31, d3
ntc_ld_lp:
			add.l d0, d0
			addx.l d2, d2
			cmp.l d1, d2
			bcs ntc_ld_no
			sub.l d1, d2
			addq.l #1, d0
ntc_ld_no:
			dbra d3, ntc_ld_lp
			tst.l d5
			bpl ntc_ld_qp
			neg.l d0
ntc_ld_qp:
			move.l d2, d1
			tst.l d4
			bpl ntc_ld_rp
			neg.l d1
ntc_ld_rp:
			jmp (a6)

			even
;## kw_l_mul ntc_lmul
kw_l_mul:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			lea kw_lmu_b, a6
			bra ntc_lmul
kw_lmu_b:
			movea.l (sp)+, a0
			move.l d0, (a0)
			rts

			even
;## kw_l_div ntc_ldiv kw_l_mul
kw_l_div:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			lea kw_lmu_b, a6
			bra ntc_ldiv

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #$01000000, d1
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "GURU 001", 0
			even

			even
;## ntc_ti89_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ti89_boot:
			; AMS entered us in user mode with a valid stack; clear the screen
			; and hand control to the thread (the compiler's start code follows,
			; sets A7 to the thread and runs).
			jsr ntc_ti89_clear
			rts

			even
;## ntc_plat_data ntc_data
; ------------------------------------------------------------
; UNVERIFIED hardware values - every one is a guess.  ;!!TI89? confirm all.
; ------------------------------------------------------------
LCD_MEM     equ $4C00           ; LCD bitmap base in RAM          ;!!TI89? guess
ROWBYTES    equ 30              ; bytes per pixel row (240/8; the 89 is 20) ;!!TI89?
SCRROWS     equ 128             ; pixel rows (the 89 is 100)       ;!!TI89?

ntc_curx:   dc.w 0              ; text column (0..cols-1)
ntc_cury:   dc.w 0              ; text row (0..rows-1)
ntc_frames: dc.w 0              ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; platform routines: entered with jsr, end with rts (real stack), keeping
; d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ti89_celladdr - a0 = LCD byte address of the top row of cell (curx,cury).
; addr = LCD_MEM + cury*8*ROWBYTES + curx   (8px-wide font = 1 byte per column)
ntc_ti89_celladdr:
			move.w ntc_cury, d1
			lsl.w #3, d1               ; row * 8 pixel rows
			mulu #ROWBYTES, d1
			add.w ntc_curx, d1
			lea LCD_MEM, a0
			adda.w d1, a0
			rts

; ntc_plat_putc - d0.b = character 32..127: blit its 8x8 glyph, advance
ntc_plat_putc:
			and.w #$00FF, d0
			sub.w #32, d0
			bge.s ntc_pc_ok
			moveq #0, d0               ; below space -> space
ntc_pc_ok:
			lsl.w #3, d0               ; glyph = font + char*8
			lea ntc_ti89_font, a1
			adda.w d0, a1
			jsr ntc_ti89_celladdr
			moveq #7, d2               ; 8 rows
ntc_pc_row:
			move.b (a1)+, (a0)
			adda.w #ROWBYTES, a0
			dbra d2, ntc_pc_row
			addq.w #1, ntc_curx
			cmp.w #30, ntc_curx        ; cols ;!!TI89? (89 = 20)
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - column 0, next row; scroll not done yet ;!!TI89? scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #16, ntc_cury        ; rows ;!!TI89? (89 = 12)
			blt.s ntc_nl_done
			move.w #15, ntc_cury
ntc_nl_done:
			rts

; ntc_ti89_clear - blank the whole LCD bitmap
ntc_ti89_clear:
			lea LCD_MEM, a0
			move.w #ROWBYTES*SCRROWS-1, d1
ntc_cl_lp:
			clr.b (a0)+
			dbra d1, ntc_cl_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data
ntc_plat_cls:
			jmp ntc_ti89_clear

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0.  ;!!TI89? the 68k calc key matrix is a
; memory-mapped port read (row strobe / column read); the exact addresses were
; NOT grounded, so this is a stub returning "no key". Wire the port + a code
; map before Inkey works. (An AMS build would ROM_CALL ngetchx instead.)
ntc_plat_scankey:
			moveq #0, d0               ; ;!!TI89? no key matrix read yet
			rts

; ntc_plat_getkey - wait for a key (spins on the stub above until wired)
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - return to AMS. ;!!TI89? a nostub program returns with rts to
; the kernel; this restores nothing special yet.
ntc_plat_exit:
			rts


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_i:			dc.w 0
ad_arr_buf:			dc.w (arr_buf)&$FFFF, (0)&$FFFF, (0)&$FFFF, (10)&$FFFF, (1)&$FFFF, (1)&$FFFF		; array as an argument
var_bytesum_bytesum:			dc.w 0
var_total_total:			dc.w 0
var_t:			dc.w 0
var_bad:			dc.w 0
p_chk_rs:			dc.l 0
var_chk_got:			dc.w 0
var_chk_want:			dc.w 0
p_bytesum_rs:			dc.l 0
var_bytesum_k:			dc.w 0
for5_l:			dc.w 0
p_total_rs:			dc.l 0
var_total_k:			dc.w 0
for6_l:			dc.w 0
tmp0:			dc.w 0
tmp1:			dc.w 0
tmp2:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			dc.b 40			; capacity
stmp1:			ds.b 41
			even
			dc.b 40			; capacity
stmp2:			ds.b 41
			even
			dc.b 40			; capacity
stmp3:			ds.b 41
			even
ltmp0:			dc.l 0
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_buf		equ ntc_bss + 0		; 10 bytes
pa_dyn		equ ntc_bss + 10		; 12 bytes
pa_names		equ ntc_bss + 22		; 12 bytes
pa_big		equ ntc_bss + 34		; 12 bytes
arr_fixed		equ ntc_bss + 46		; 10 bytes
pa_dyn_data		equ ntc_bss + 56		; 42 bytes
pa_names_data		equ ntc_bss + 98		; 123 bytes
pa_big_data		equ ntc_bss + 222		; 8 bytes
pa_recs_n		equ ntc_bss + 230		; 12 bytes
pa_recs_n_data		equ ntc_bss + 242		; 10 bytes
pa_recs_nm		equ ntc_bss + 252		; 12 bytes
pa_recs_nm_data		equ ntc_bss + 264		; 205 bytes
pa_bytesum_b		equ ntc_bss + 470		; 12 bytes
pa_total_a		equ ntc_bss + 482		; 12 bytes
ntc_bss_size	equ 494
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
